(()=>{
const books=[['The Adventures of Sherlock Holmes','Arthur Conan Doyle','Twelve cases follow Holmes and Watson through puzzling clues, disguises, and unexpected motives. A collection of short mysteries built around observation and deduction.','https://www.gutenberg.org/ebooks/1661'],['The Mystery of the Burnt Cottage','Enid Blyton','The Five Find-Outers and their dog investigate a mysterious fire in Peterswood. Their first adventure brings together a team of young detectives determined to discover what happened.','https://www.hachette.co.uk/titles/enid-blyton-2/the-find-outers-the-mystery-of-the-burnt-cottage/9781444926859/'],['The Five Find-Outers and Dog','Enid Blyton','A mystery series following Fatty, Larry, Daisy, Pip, Bets, and Buster the dog. Clues, disguises, and teamwork help the children untangle unusual events around Peterswood.','https://www.enidblyton.co.uk/landing-page/enid-blyton/enid-blyton-books/enid-blyton-the-mystery-series/']];
const shelf=document.createElement('div');shelf.className='extra-books';document.querySelector('.reading-room').after(shelf);
const dialog=document.createElement('dialog');dialog.className='reading-summary';dialog.innerHTML='<button class="close-dialog" aria-label="Close summary">×</button><p class="eyebrow"></p><h2 id="extra-title"></h2><p class="summary-copy"></p><a class="text-link" target="_blank" rel="noopener noreferrer">Book information ↗</a>';dialog.setAttribute('aria-labelledby','extra-title');document.body.append(dialog);let opener;dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>opener?.focus({preventScroll:true}));
books.forEach((book,i)=>{const b=document.createElement('button');b.className='reading-book';b.style.backgroundColor=['#414e68','#70503c','#544064'][i];b.setAttribute('aria-haspopup','dialog');const author=document.createElement('span');author.className='book-author';author.textContent=book[1];const title=document.createElement('strong');title.textContent=book[0];const mark=document.createElement('span');mark.className='book-bird';mark.textContent=i?'◇':'⌕';const foot=document.createElement('span');foot.textContent='Open summary ↗';b.append(author,mark,title,foot);shelf.append(b);b.onclick=()=>{opener=b;dialog.querySelector('.eyebrow').textContent=book[1];dialog.querySelector('h2').textContent=book[0];dialog.querySelector('.summary-copy').textContent=book[2];dialog.querySelector('a').href=book[3];dialog.showModal();};});
const games=['Need for Speed Heat','Cyberpunk 2077','F1 25','Watch Dogs 2','Mount & Blade II: Bannerlord','Hogwarts Legacy','EA SPORTS FC 26','Where Winds Meet','Planet Zoo','PC Building Simulator','Marvel Rivals','Jurassic World Evolution 2','Assassin’s Creed Origins','Age of Empires III: Definitive Edition','Batman: Arkham Knight','Battlefield V','Catch Me!','Car Parking Multiplayer 2','Dead Island Definitive Edition','Delta Force','Dishonored','Europa Universalis IV','THE FINALS','First Racer'];
const host=document.querySelector('#steam-collection');games.forEach((name,i)=>{const a=document.createElement('a');a.href='https://store.steampowered.com/search/?term='+encodeURIComponent(name);a.target='_blank';a.rel='noopener noreferrer';a.style.setProperty('--game-hue',String((i*43)%360));const number=document.createElement('span');number.textContent=String(i+1).padStart(2,'0')+' / COLLECTION';const title=document.createElement('h2');title.textContent=name;const foot=document.createElement('small');foot.textContent='Find on Steam ↗';a.append(number,title,foot);host.append(a);});
for(const id of ['books','board-games']){const a=document.createElement('a');a.className='text-link room-return';a.href='#living-room';a.textContent='← Living Room';document.getElementById(id).prepend(a);}
})();
